// generated by bise-proto (rust/proto/tests/ts.rs), never hand-edited:
// BISE_PROTO_BLESS=1 cargo test -p bise-proto --features ts --test ts
// ids, positions and *_ms are numbers (u64 in Rust, safe below 2^53).

export type LineKind = "ctx" | "add" | "del";

export type DiffLine = { kind: LineKind, old?: number | null, new?: number | null, text: string, };

export type Hunk = { header: string, lines: Array<DiffLine>, 
/**
 * git's function context after the `@@` (the terminal's `@@ head @@`)
 */
head?: string | null, 
/**
 * its id in a guide: a short hash of its file's path and its removed
 * and added lines, stable across pushes while the hunk is the same
 * (switchboard's guide::hunk_id; never computed by a client)
 */
id?: string | null, };

export type DiffFile = { path: string, 
/**
 * added, modified, deleted, renamed
 */
status: string, add: number, del: number, hunks: Array<Hunk>, 
/**
 * its hunks were cut (past the size cap, or binary): the review says
 * so, never shows it as complete
 */
truncated?: boolean, 
/**
 * a renamed file's old path ("renamed from decode.rs")
 */
from?: string | null, 
/**
 * a binary file: no lines (`truncated` too), its words are its own
 */
binary?: boolean, 
/**
 * a generated file (a lock file, a build output): a display flag,
 * the client folds it (its lines are sent, under the same size cap)
 */
generated?: boolean, 
/**
 * an image (by its extension): the terminal says so and opens it
 */
image?: boolean, 
/**
 * its size in bytes after the change, for a binary file still there
 * ("a binary file, 2.1 MB")
 */
size?: number | null, 
/**
 * the agent's word on this file ("new: 4 workers"), from its summary
 */
note?: string | null, 
/**
 * its absolute path in the checkout the diff was read in (the
 * terminal's /diff opens it), none when that folder is gone
 */
abs?: string | null, };

/**
 * What a change measured, before and after (the review's result line,
 * amb-web m_8304): "worst frame, PS5 replay · forest level 40 → 15 ms".
 */
export type DiffResult = { label: string, sub?: string | null, before: number, after: number, unit: string, series?: Series | null, };

export type Series = { before: Array<number>, after: Array<number>, };

/**
 * The terminal's `/diff` fields of a `diff` (client-protocol step 3),
 * next to the review's on the wire: its title ("perf vs main", "range
 * a..b"), the `req` it answers, the commits ahead of the base, the agent
 * still working, edits not committed yet, when it landed, its folder
 * gone.
 */
export type DiffView = { title?: string | null, req?: number | null, commits?: number | null, working?: boolean, uncommitted?: boolean, landed_ms?: number | null, gone?: boolean, 
/**
 * a `.diff` artifact's diff (the `diff` ask's `artifact`): its id and
 * the version read; a client keys the answer by them
 */
artifact?: string | null, version?: number | null, };

/**
 * How much a guide's part matters to the change (page review-guided). A
 * label only: the review shows every part, never folds or skips one by
 * its weight (architect m_57259: the guide never hides code).
 */
export type Weight = "critical" | "normal" | "context";

/**
 * One part of a guide: an idea of the change, its hunks in reading order.
 */
export type GuidePart = { 
/**
 * where it is, 1-2 words ("Sidebar", "Tests")
 */
area: string, 
/**
 * 2-6 words that name the idea, never a file ("Give the row's end one owner")
 */
title: string, 
/**
 * at most two lines, plain text
 */
summary: string, 
/**
 * its hunks' ids ([`Hunk::id`]), in the order to read them
 */
hunks: Array<string>, weight: Weight, };

/**
 * A change's guide, written by the small jobs model (switchboard's
 * guide.rs). Every hunk of the diff is in exactly one part or in `rest`.
 */
export type Guide = { 
/**
 * three lines at most: what the change does, plain text
 */
overview: string, parts: Array<GuidePart>, 
/**
 * the hunks out of the story (glue, docs, generated, repeats)
 */
rest: Array<string>, };

/**
 * The diff a `guide` ask is about: the same diffs as the review's
 * (an agent's change, a commit, a PR by its link, a branch).
 */
export type GuideTarget = { "kind": "agent", name: string, } | { "kind": "commit", agent: string, sha: string, } | { "kind": "pr", url: string, } | { "kind": "branch", name: string, };

/**
 * Where a diff's guide stands (the `guide` event).
 */
export type GuideState = "none" | "small" | "writing" | "ready" | "failed" | "needs_click" | "unknown";
